 "identite_visuelle":{"direction":"description précise du parti pris artistique","palette":["#hex","#hex","#hex","#hex"],"typographie":"indication de hiérarchie typographique"},
 "profil":{"pseudo":"","portrait":"description éditoriale prudente en 2 phrases","niveau_influence":{"label":"lecture indicative","score":0},"preoccupations":["..."],"limites":"ce que les données ne permettent pas d'affirmer"},
 "5w":{"who":"...","what":"...","when":"...","where":"...","why":"...","how":"..."},
