function agnes(string $system,string $user,array $c,int $modelOffset=0,?int $tokenOverride=null): array {
 $keys=array_values(array_filter(array_map('trim',(array)$c['keys'])));
 if(!$keys)throw new Exception('Aucune clé Agnès configurée dans Administration.');
 $models=array_values(array_filter((array)$c['models']));
 if(!$models)throw new Exception('Aucun modèle Agnès configuré dans Administration.');
 $last='aucune réponse';
 foreach(array_slice($models,$modelOffset) as $model){
  foreach($keys as $ki=>$key){
   $limit=$tokenOverride!==null?max(1000,min(12000,$tokenOverride)):(int)$c['max_tokens'];
   $payload=['model'=>$model,'temperature'=>(float)$c['temperature'],'max_tokens'=>$limit,'messages'=>[['role'=>'system','content'=>$system],['role'=>'user','content'=>$user]]];
   $r=http_req('https://apihub.agnes-ai.com/v1/chat/completions',['timeout'=>110,'headers'=>['Content-Type: application/json','Authorization: Bearer '.$key],'post'=>json_encode($payload,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)]);
   $j=json_decode($r['body'],true);
   $choice=$j['choices'][0]??[];
   $txt=$choice['message']['content']??null;
   if(is_array($txt)){$parts=[];foreach($txt as $part)if(is_array($part)&&isset($part['text']))$parts[]=(string)$part['text'];$txt=implode("\n",$parts);}
   if($r['code']===200&&is_string($txt)&&trim($txt)!=='')return ['text'=>$txt,'model'=>$model,'finish_reason'=>(string)($choice['finish_reason']??''),'usage'=>$j['usage']??null];
   $detail=$j['error']['message']??$j['message']??$r['error']??'réponse vide';
   $last=$model.' / clé '.($ki+1).' / HTTP '.$r['code'].' / '.mb_substr((string)$detail,0,150);
   error_log('CHRONOS Agnès: '.$last.' / body='.mb_substr((string)$r['body'],0,900));
  }
 }
 throw new Exception('Agnès indisponible : '.$last);
}
function parse_json(string $s): ?array {
 $s=trim(preg_replace('/^\xEF\xBB\xBF/','',$s));
 $s=preg_replace('/^\s*```(?:json)?\s*/i','',$s);
 $s=preg_replace('/\s*```\s*$/','',$s);
 // Repère le premier objet JSON équilibré, sans confondre les accolades dans les chaînes.
 $start=strpos($s,'{'); if($start===false)return null;
 $depth=0;$inString=false;$escape=false;$end=null;$len=strlen($s);
 for($i=$start;$i<$len;$i++){
  $ch=$s[$i];
  if($inString){if($escape){$escape=false;continue;}if($ch==='\\'){$escape=true;continue;}if($ch==='"')$inString=false;continue;}
  if($ch==='"'){$inString=true;continue;}
  if($ch==='{')$depth++;
  elseif($ch==='}'){$depth--;if($depth===0){$end=$i;break;}if($depth<0)return null;}
 }
 if($end===null)return null;
 $json=substr($s,$start,$end-$start+1);
 $decoded=json_decode($json,true);
 return is_array($decoded)?$decoded:null;
}
function clean_scenario(array $s): array {$s['scenes']=array_slice(array_values(array_filter((array)($s['scenes']??[]),'is_array')),0,14);if(count($s['scenes'])<3)throw new Exception('Le scénario IA contient trop peu de scènes. Relance la génération.');foreach($s['scenes'] as $i=>&$scene){$scene['id']=preg_replace('/[^a-zA-Z0-9_-]/','',(string)($scene['id']??'s'.($i+1)));foreach(['titre','narration','ecran','citation','fait_cle','transition','visual_brief','svg','role','mood'] as $k)$scene[$k]=is_string($scene[$k]??null)?$scene[$k]:'';if(strlen($scene['svg'])>24000)$scene['svg']=substr($scene['svg'],0,24000);if($scene['svg']==='')$scene['svg']='<g><text x="360" y="570" text-anchor="middle" font-size="34" fill="#20252c">Illustration non fournie</text></g>'; }unset($scene);return $s;}

/**
 * Phase 2: génère les SVG indépendamment du récit.
 * Le modèle ne doit plus produire 9 illustrations dans la même réponse JSON.
 * Les lots sont petits ; en cas de lot tronqué, on bascule scène par scène.
 */
function generate_scene_svg_batch(array $scenes,array $c,int $modelOffset=0): array {
 if(!$scenes)return [];
 $spec=[];
 foreach($scenes as $sc)$spec[]=[
  'id'=>(string)($sc['id']??''),
  'role'=>(string)($sc['role']??''),
  'titre'=>(string)($sc['titre']??''),
  'narration'=>(string)($sc['narration']??''),
  'ecran'=>(string)($sc['ecran']??''),
  'fait_cle'=>(string)($sc['fait_cle']??''),
  'visual_brief'=>(string)($sc['visual_brief']??''),
  'mood'=>(string)($sc['mood']??'')
 ];
 $system="Tu es un directeur artistique et illustrateur SVG. Tu reçois des scènes documentaires déjà écrites. Pour chaque scène, dessine une illustration SVG originale et différente, strictement adaptée à son contenu. Réponds UNIQUEMENT en JSON valide sous la forme {\"scenes\":[{\"id\":\"identifiant exact\",\"svg\":\"fragment SVG\"}]}. Le fragment ne doit PAS contenir la balise svg racine. viewBox logique 0 0 720 1280. Utilise uniquement g,path,rect,circle,ellipse,line,polyline,polygon,text,tspan,defs,linearGradient,radialGradient,stop,clipPath. Aucun script, événement, image externe, foreignObject ou CSS externe. Composition expressive, lisible sur mobile, détails essentiels uniquement. 500 à 1000 caractères SVG par scène. Pas de décor générique répété. Fais varier la composition selon le sujet. Tous les textes SVG courts, en français, et orthographiés. Retourne tous les identifiants reçus, sans en inventer.";
 $user="Génère les illustrations des scènes suivantes. Le texte et les faits sont figés : ne les réécris pas, ne les complète pas, n'invente aucune donnée.\n".json_encode(['scenes'=>$spec],JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES|JSON_INVALID_UTF8_SUBSTITUTE);
 $r=agnes($system,$user,$c,$modelOffset,min(3200,(int)$c['max_tokens']));
 $j=parse_json($r['text']);
 if(!$j||empty($j['scenes'])||!is_array($j['scenes'])||$r['finish_reason']==='length')return [];
 $out=[];
 foreach($j['scenes'] as $item){
  if(!is_array($item)||empty($item['id'])||!isset($item['svg'])||!is_string($item['svg']))continue;
  $svg=trim($item['svg']);
  // Accepte aussi une racine svg fournie par le modèle, puis extrait son contenu.
  if(preg_match('/^<svg\b[^>]*>(.*)<\/svg>\s*$/is',$svg,$m))$svg=$m[1];
  if($svg!=='' && strlen($svg)<=24000 && stripos($svg,'<script')===false && stripos($svg,'foreignObject')===false)$out[(string)$item['id']]=$svg;
 }
 return $out;
}
function generate_all_scene_svgs(array &$scenes,array $c): void {
 // Lots de deux scènes pour limiter le volume de chaque réponse.
 foreach(array_chunk(array_keys($scenes),2) as $batchKeys){
  $batch=[];foreach($batchKeys as $idx)$batch[]=$scenes[$idx];
  $svgs=[];
  try{$svgs=generate_scene_svg_batch($batch,$c,0);}catch(Throwable $e){error_log('CHRONOS SVG batch: '.$e->getMessage());}
  // Repli : appels unitaires, beaucoup moins susceptibles d'être tronqués.
  foreach($batch as $sc){
   $id=(string)$sc['id'];
   if(!empty($svgs[$id]))continue;
   try{$one=generate_scene_svg_batch([$sc],$c, count((array)$c['models'])>1?1:0);if(!empty($one[$id]))$svgs[$id]=$one[$id];}
   catch(Throwable $e){error_log('CHRONOS SVG scene '.$id.': '.$e->getMessage());}
  }
  foreach($batchKeys as $idx){$id=(string)$scenes[$idx]['id'];if(!empty($svgs[$id]))$scenes[$idx]['svg']=$svgs[$id];}
 }
}


