  $dataJson=json_encode($d,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES|JSON_INVALID_UTF8_SUBSTITUTE);
  $userBase=str_replace(['{{DATA}}','{{SUBTITLES}}','{{NSCENES}}'],[$dataJson,$subs!==''?$subs:'(aucun sous-titre disponible ; ne pas inventer de propos)',(string)$n],(string)$c['prompt_user']);

  // PHASE 1 — récit, 5W et direction artistique uniquement. Aucun SVG ici.
  // Cela protège le contenu éditorial de la limite de sortie consommée par les dessins.
  $phase1System=(string)$c['prompt_system']
   . "\n\nPHASE 1 OBLIGATOIRE : produis uniquement le scénario éditorial et les fiches de scènes. Pour chaque scène, le champ svg doit être une chaîne vide. Ne dessine aucun SVG dans cette phase. Conserve les champs JSON attendus, notamment titre, narration, ecran, citation, fait_cle, transition, visual_brief, role et mood. Chaque narration doit être complète et exploitable. Réponse JSON complète obligatoire.";
  $phase1User=$userBase
   . "\n\nRAPPEL PHASE 1 : ne génère AUCUN SVG. Dans chaque objet de scène, renseigne \"svg\":\"\". Le champ visual_brief doit décrire précisément une composition originale à dessiner lors d'une étape séparée.";
  $phaseTokens=min(5200,(int)$c['max_tokens']);
  $r=agnes($phase1System,$phase1User,$c,0,$phaseTokens);
  $s=parse_json($r['text']);
  if(!$s || $r['finish_reason']==='length'){
   $retryN=max(5,min($n,7));
   $retryUser=str_replace('{{NSCENES}}',(string)$retryN,$phase1User);
   $retrySystem=$phase1System."\nSECONDE TENTATIVE : limite le scénario à ".$retryN." scènes. Chaque narration fait 2 phrases concises. N'ajoute aucune illustration, aucun SVG. Termine impérativement le JSON.";
   try{$r=agnes($retrySystem,$retryUser,$c,count((array)$c['models'])>1?1:0,min(4800,(int)$c['max_tokens']));$s=parse_json($r['text']);}
   catch(Throwable $retryError){error_log('CHRONOS récit retry: '.$retryError->getMessage());}
  }
  if(!$s){
   $raw=trim((string)($r['text']??''));$finish=(string)($r['finish_reason']??'inconnu');
   error_log('CHRONOS récit JSON invalide; modèle='.($r['model']??'inconnu').'; finish='.$finish.'; longueur='.strlen($raw).'; extrait='.mb_substr($raw,0,1600));
   $msg=$finish==='length'?'Le récit seul dépasse encore la limite de sortie du modèle. Réduis le nombre de scènes ou utilise un modèle avec une fenêtre de sortie plus grande.':'Le récit Agnès est incomplet ou mal formé. Consulte data/error.log.';
   out(['ok'=>false,'error'=>$msg,'model'=>$r['model']??'','finish_reason'=>$finish,'response_length'=>strlen($raw)],502);
  }
  try{$s=clean_scenario($s);}catch(Throwable $e){out(['ok'=>false,'error'=>'Le récit reçu est incomplet : '.$e->getMessage()],502);}

  // PHASE 2 — illustrations SVG en lots de deux, puis appel individuel si un lot échoue.
  // clean_scenario ajoute un placeholder pour les SVG vides : on le retire avant la génération IA.
  foreach($s['scenes'] as &$scene)$scene['svg']='';unset($scene);
  generate_all_scene_svgs($s['scenes'],$c);
  // Fallback visible si le fournisseur ne produit pas un SVG : la narration reste disponible.
  foreach($s['scenes'] as $i=>&$scene){
   if(trim((string)($scene['svg']??''))===''){
    $label=htmlspecialchars(mb_substr((string)($scene['ecran']?:$scene['titre']),0,52),ENT_QUOTES|ENT_XML1,'UTF-8');
    $scene['svg']='<g><rect x="42" y="420" width="636" height="330" rx="18" fill="#172b3a" stroke="#69e1e8" stroke-width="2"/><text x="360" y="570" text-anchor="middle" font-size="27" fill="#ffffff">'.$label.'</text><text x="360" y="625" text-anchor="middle" font-size="15" fill="#9db5c6">ILLUSTRATION NON DISPONIBLE</text></g>';
   }
  }unset($scene);
  out(['ok'=>true,'scenario'=>$s,'model'=>$r['model']??'','visuals'=>'generated_in_separate_calls']);
 }
 if($api==='admin_state')out(['ok'=>true,'first'=>empty($c['admin_hash']),'logged'=>!empty($_SESSION['adm'])]);
 if($api==='admin_login'){if(empty($c['admin_hash'])){if(strlen((string)($in['pw']??''))<10)out(['ok'=>false,'error'=>'Choisis un mot de passe de 10 caractères minimum.'],400);$c['admin_hash']=password_hash((string)$in['pw'],PASSWORD_DEFAULT);cfg_save($c);$_SESSION['adm']=1;$_SESSION['csrf']=bin2hex(random_bytes(24));out(['ok'=>true,'created'=>true]);}usleep(350000);if(password_verify((string)($in['pw']??''),(string)$c['admin_hash'])){session_regenerate_id(true);$_SESSION['adm']=1;$_SESSION['csrf']=bin2hex(random_bytes(24));out(['ok'=>true]);}out(['ok'=>false,'error'=>'Mot de passe incorrect.'],401);}
 if(empty($_SESSION['adm']))out(['ok'=>false,'error'=>'Session administrateur requise.'],401);
 if($api==='admin_get'){$o=$c;unset($o['admin_hash']);$o['csrf']=$_SESSION['csrf'];$o['defaults']=['prompt_system'=>defaults()['prompt_system'],'prompt_user'=>defaults()['prompt_user']];out(['ok'=>true,'config'=>$o]);}
 if(!hash_equals((string)($_SESSION['csrf']??''),(string)($in['csrf']??'')))out(['ok'=>false,'error'=>'Jeton de sécurité invalide.'],403);
 if($api==='admin_save'){$n=$in['config']??[];$c['prompt_system']=(string)($n['prompt_system']??$c['prompt_system']);$c['prompt_user']=(string)($n['prompt_user']??$c['prompt_user']);$c['models']=array_values(array_filter(array_map('trim',explode(',',(string)($n['models']??implode(',',$c['models']))))));$c['keys']=array_values(array_filter(array_map('trim', preg_split('/\s+/', (string)($n['keys'] ?? implode("\n", $c['keys']))))));$c['temperature']=max(0,min(1.5,(float)($n['temperature']??$c['temperature'])));$c['max_tokens']=max(1500,min(12000,(int)($n['max_tokens']??$c['max_tokens'])));$c['nscenes']=max(5,min(12,(int)($n['nscenes']??$c['nscenes'])));$c['rate_per_hour']=max(1,min(200,(int)($n['rate_per_hour']??$c['rate_per_hour'])));if(!empty($n['new_pw'])){if(strlen((string)$n['new_pw'])<10)out(['ok'=>false,'error'=>'10 caractères minimum pour le mot de passe.'],400);$c['admin_hash']=password_hash((string)$n['new_pw'],PASSWORD_DEFAULT);}cfg_save($c);out(['ok'=>true]);}
 if($api==='admin_logout'){$_SESSION=[];session_destroy();out(['ok'=>true]);}out(['ok'=>false,'error'=>'Action inconnue.'],404);
}catch(Throwable $e){error_log('CHRONOS '.$api.': '.$e->getMessage());out(['ok'=>false,'error'=>$e->getMessage()],500);}
?>
<!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#10151d"><title>CHRONOS — Visual Storytelling Engine</title>
<style>
