e);box-shadow:0 16px 50px #0003;border-radius:3px}.panelHead{display:flex;justify-content:space-between;align-items:center;padding:15px 16px;border-bottom:1px solid var(--line);font:10px var(--mono);letter-spacing:.16em;color:#a9b8c7}.panelHead em{font-style:normal;color:var(--cyan)}.panelBody{padding:16px}.fieldLabel{display:block;color:#91a2b4;font:10px var(--mono);letter-spacing:.12em;margin:0 0 8px}.urlInput,.adminInput,.adminArea{width:100%;background:#0b121b;border:1px solid #314457;color:#e9f2fa;padding:13px 14px;outline:0;border-radius:2px}.urlInput:focus,.adminInput:focus,.adminArea:focus{border-color:var(--cyan);box-shadow:0 0 0 2px #69e1e81a}.primary{border:1px solid var(--cyan);background:var(--cyan);color:#071216;padding:12px 16px;font:11px var(--mono);letter-spacing:.12em;text-transform:uppercase;font-weight:700}.primary:hover{background:#a5f5f5}.secondary{border:1px solid #40546a;background:transparent;color:#c3d1de;padding:11px 14px;font:10px var(--mono);letter-spacing:.1em}.secondary:hover{border-color:var(--cyan);color:var(--cyan)}.actionRow{display:flex;gap:8px;margin-top:10px}.actionRow>*{flex:1}.hint{color:#78899b;font-size:11px;margin:12px 0 0}.log{height:190px;overflow:auto;font:10px/1.8 var(--mono);color:#93a6b9}.log .ok{color:var(--lime)}.log .err{color:#ff8d78}.log .info{color:var(--cyan)}.stagePanel{padding:13px}.stageTop{display:flex;justify-content:space-between;align-items:center;margin:0 2px 12px;color:#9aabbb;font:10px var(--mono);letter-spacing:.12em}.liveDot{display:inline-block;width:6px;height:6px;border-radius:50%;background:var(--lime);margin-right:7px;box-shadow:0 0 12px var(--lime)}#stageWrap{position:relative;max-width:470px;margin:auto;background:#090e14;border:1px solid #34485c;box-shadow:0 24px 70px #0008;overflow:hidden}#stage{display:block;width:100%;aspect-ratio:9/16;background:#121b27}#stage .sceneGroup{transform-box:fill-box;transform-origin:center;will-change:opacity,transform}#stage .sceneGroup.active{opacity:1}#stage .sceneGroup.inactive{opacity:0;pointer-events:none}.emptyState{position:absolute;inset:0;display:grid;place-items:center;text-align:center;padding:30px;color:#9aabba;background:radial-gradient(ellipse at 50% 40%,#263b4c,#101720 68%)}.emptyState strong{display:block;font:clamp(26px,4vw,42px) var(--serif);font-weight:400;color:#eaf3f7}.emptyState span{font:10px var(--mono);letter-spacing:.18em;color:var(--cyan)}.transport{display:flex;align-items:center;gap:8px;margin:13px 0 2px}.transport button{min-width:42px}.transport input{flex:1;accent-color:var(--cyan)}.timecode{font:10px var(--mono);color:#8fa2b5;min-width:88px;text-align:right}.readProgress{height:2px;background:#243447;margin:12px 0 0}.readProgress span{display:block;height:100%;width:0;background:var(--cyan)}.storyNav{display:flex;gap:6px;flex-wrap:wrap;margin-top:12px}.storyNav button{border:1px solid #304256;background:#101a25;color:#90a2b4;padding:6px 8px;font:9px var(--mono)}.storyNav button.active{border-color:var(--cyan);color:var(--cyan);background:#19303a}.rightStack{display:grid;gap:14px}.metricGrid{display:grid;grid-template-columns:1fr 1fr;gap:8px}.metric{padding:10px;background:#0c141e;border:1px solid #26394b}.metric span{display:block;color:#8295a8;font:9px var(--mono);letter-spacing:.1em}.metric b{display:block;font:20px var(--serif);font-weight:400;margin-top:3px}.dataText{color:#aab8c5;font-size:12px;line-height:1.65;overflow-wrap:anywhere}.subText{max-height:180px;overflow:auto;white-space:pre-wrap}.storyList{font:11px/1.65 var(--mono);color:#9caebe}.storyList button{display:block;width:100%;text-align:left;padding:8px 0;border:0;border-bottom:1px solid #263647;background:none;color:inherit}.storyList button:hover{color:var(--cyan)}.storyList b{color:var(--cyan);font-weight:400}.progressBox{display:none;margin-top:14px;padding:12px;border:1px solid #345165;background:#10202b}.progressBox.show{display:block}.progressTitle{font:10px var(--mono);color:var(--cyan);letter-spacing:.13em}.progressBar{height:3px;background:#283a4b;margin-top:10px;overflow:hidden}.progressBar i{display:block;height:100%;width:35%;background:var(--cyan);animation:loading 1.2s ease-in-out infinite alternate}@keyframes loading{from{transform:translateX(-25%)}to{transform:translateX(190%)}}.below{display:grid;grid-template-columns:1.3fr 1fr;gap:18px;margin-top:18px}.narration{font:clamp(17px,2vw,23px)/1.5 var(--serif);color:#e5edf3}.narration small{display:block;font:9px var(--mono);letter-spacing:.16em;color:var(--cyan);margin-bottom:10px}.factLine{border-left:2px solid var(--orange);padding-left:12px;color:#c3d0dc;font-size:12px;margin-top:14px}.fivew{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}.fivew div{background:#0c141e;border:1px solid #27394a;padding:10px}.fivew b{display:block;color:var(--cyan);font:10px var(--mono);margin-bottom:5px}.fivew span{font-size:11px;color:#b7c4cf}.modal{display:none;position:fixed;inset:0;background:#05090edb;z-index:30;overflow:auto;padding:24px}.modalInner{max-width:900px;margin:4vh auto;background:#101a25;border:1px solid #385064;padding:20px}.modal h2{font:24px var(--serif);font-weight:400}.modal label{display:block;font:10px var(--mono);color:#9eb0c0;letter-spacing:.1em;margin:15px 0 6px}.adminArea{min-height:100px;font:11px/1.5 var(--mono);resize:vertical}.adminGrid{display:grid;grid-template-columns:repeat(2,1fr);gap:12px}.modalActions{display:flex;gap:8px;margin-top:18px}.modalActions button{flex:1}.toast{position:fixed;right:18px;bottom:18px;background:#152637;border:1px solid #47657d;color:#eaf5fb;padding:12px 16px;font:11px var(--mono);z-index:50;display:none;max-width:360px}.toast.show{display:block}@media(max-width:1150px){.layout{grid-template-columns:270px minmax(340px,1fr)}.rightStack{grid-column:1/-1;grid-template-columns:repeat(3,1fr)}}@media(max-width:760px){.top{height:60px}.topmeta{display:none}.hero{display:block}.heroTag{display:inline-block;margin-top:14px}.layout{grid-template-columns:1fr}.rightStack{gr