<header class="top"><div class="brand"><div class="brandmark"><span>✳</span></div><div><strong>CHRONOS</strong><small>AI VISUAL STORYTELLING ENGINE · 02</small></div></div><div class="topmeta"><b>● SYSTEM READY</b> &nbsp; / &nbsp; <span id="clock">--:--:--</span> &nbsp; / &nbsp; SILENT DOCUMENTARY</div></header>
<div class="shell"><section class="hero"><div><div class="eyebrow">A new way to understand information</div><h1>Make the facts<br><i>come alive.</i></h1><p>Une lecture documentaire qui transforme les données en récit, et chaque idée en une scène visuelle conçue par l'intelligence artificielle.</p></div><div class="heroTag">NO FIXED TEMPLATE&nbsp; / &nbsp;SVG GENERATED PER STORY</div></section>
<div class="layout"><aside class="panel"><div class="panelHead"><span>01 / SOURCE</span><em>INPUT</em></div><div class="panelBody"><label class="fieldLabel" for="url">URL DE LA VIDÉO TIKTOK</label><input class="urlInput" id="url" type="url" placeholder="https://www.tiktok.com/@.../video/..." autocomplete="off"><div class="actionRow"><button class="primary" id="go">Analyser & créer</button><button class="secondary" id="admBtn">Admin</button></div><p class="hint">Collecte des données publiques, sous-titres disponibles et contexte du compte. Les informations absentes restent explicitement inconnues.</p><div class="progressBox" id="progress"><div class="progressTitle" id="progressTitle">ANALYSE EN COURS</div><div class="progressBar"><i></i></div><p class="hint" id="progressHint">L'IA construit le récit et dessine les scènes.</p></div></div><div class="panelHead"><span>02 / JOURNAL</span><em id="status">STANDBY</em></div><div class="panelBody"><div class="log" id="log"><div class="info">10:23:00 — CHRONOS ready.</div><div>En attente d'une source TikTok.</div></div></div></aside>
<section class="panel stagePanel"><div class="stageTop"><span><i class="liveDot"></i><span id="stageStatus">VISUAL CANVAS</span></span><span id="sceneCount">00 / 00</span></div><div id="stageWrap"><svg id="stage" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 720 1280" role="img" aria-label="Animation documentaire générée par IA"><rect width="720" height="1280" fill="#111b27"/><g id="sceneLayer"></g></svg><div class="emptyState" id="empty"><div><span>CHRONOS / WAITING FOR DATA</span><strong>Une histoire<br>à découvrir.</strong><p>Colle une URL TikTok pour commencer.</p></div></div></div><div class="transport"><button class="secondary" id="play" title="Lecture">▶</button><button class="secondary" id="prev" title="Scène précédente">‹</button><input id="scrub" type="range" min="0" max="1000" value="0"><button class="secondary" id="next" title="Scène suivante">›</button><span class="timecode" id="timecode">00:00 / 00:00</span><button class="secondary" id="fs" title="Plein écran">⛶</button></div><div class="readProgress"><span id="readProgress"></span></div><div class="storyNav" id="storyNav"></div></section>
<aside class="rightStack"><div class="panel"><div class="panelHead"><span>03 / DATA SNAPSHOT</span><em id="source">—</em></div><div class="panelBody"><div class="metricGrid" id="metrics"><div class="metric"><span>FOLLOWERS</span><b>—</b></div><div class="metric"><span>VIEWS</span><b>—</b></div><div class="metric"><span>LIKES</span><b>—</b></div><div class="metric"><span>COMMENTS</span><b>—</b></div></div><p class="dataText" id="accountInfo">Les données du compte apparaîtront ici.</p></div></div><div class="panel"><div class="panelHead"><span>04 / TRANSCRIPT</span><em id="subCount">0</em></div><div class="panelBody"><div class="dataText subText" id="subs">Aucun sous-titre chargé.</div></div></div><div class="panel"><div class="panelHead"><span>05 / STORY STRUCTURE</span><em id="model">—</em></div><div class="panelBody"><div class="storyList" id="storyList">Le plan narratif apparaîtra après l'analyse.</div></div></div></aside></div>
<div class="below"><section class="panel"><div class="panelHead"><span>06 / NARRATION</span><em id="narrationRole">WAITING</em></div><div class="panelBody"><div class="narration" id="narration"><small>SCÈNE COURANTE</small>La narration et les explications apparaîtront ici pendant la lecture.</div><div class="factLine" id="factLine">Les faits essentiels seront explicités sans extrapolation.</div></div></section><section class="panel"><div class="panelHead"><span>07 / THE 5W + HOW</span><em>UNDERSTANDING MAP</em></div><div class="panelBody"><div class="fivew" id="fivew"><div><b>WHO / QUI</b><span>—</span></div><div><b>WHAT / QUOI</b><span>—</span></div><div><b>WHEN / QUAND</b><span>—</span></div><div><b>WHERE / OÙ</b><span>—</span></div><div><b>WHY / POURQUOI</b><span>—</span></div><div><b>HOW / COMMENT</b><span>—</span></div></div></div></section></div></div>
<div class="modal" id="modal"><div class="modalInner"><div style="display:flex;justify-content:space-between;align-items:center"><h2>Administration CHRONOS</h2><button class="secondary" id="mclose">Fermer ×</button></div><div id="mLogin"><label id="mLabel">MOT DE PASSE ADMIN</label><input class="adminInput" type="password" id="mpw"><div class="modalActions"><button class="primary" id="mgo">Connexion</button></div></div><div id="mForm" style="display:none"><label>INSTRUCTIONS SYSTÈME — DIRECTION ÉDITORIALE ET VISUELLE</label><textarea class="adminArea" id="c_ps" rows="12"></textarea><label>PROMPT DE PRODUCTION — {{DATA}} {{SUBTITLES}} {{NSCENES}}</label><textarea class="adminArea" id="c_pu" rows="17"></textarea><div class="adminGrid"><div><label>MODÈLES (séparés par virgule)</label><input class="adminInput" id="c_mod"></div><div><label>TEMPÉRATURE</label><input class="adminInput" type="number" step=".05" id="c_t"></div><div><label>MAX TOKENS (SVG + narration)</label><input class="adminInput" type="number" id="c_mt"></div><div><label>NOMBRE DE SCÈNES CIBLE</label><input class="adminInput" type="number" id="c_ns"></div><div><label>LIMITE PAR HEURE / IP</label><input class="adminInput" type="number" id="c_rl"></div><div><label>NOUVEAU MOT DE PASSE (10+ CARACTÈRES)</label><input class="adminInput" type="password" id="c_pw"></div></div><label>CLÉS API AGNÈS — UNE PAR LIGNE</label><textarea class="adminArea" id="c_k" rows="5" placeholder="Une clé par ligne"></textarea><div class="modalActions"><button class="primary" id="msave">Enregistrer</button><button class="secondary" id="rst">Prompts par défaut</button><button class="secondary" id="mout">Déconnexion</button></div></div></div></div><div class="toast" id="toast"></div>
<script>
'use strict';const $=id=>document.getElementById(id),NS='http://www.w3.org/2000/svg';let csrf='',defaults={},dataSet=null,story=null,scenes=[],durations=[],starts=[],total=0,current=0,playing=false,raf=0,startedAt=0,offset=0;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const fmt=n=>{n=Number(n)||0;return n>=1e6?(n/1e6).toFixed(1)+' M':n>=1e3?(n/1e3).toFixed(1)+' k':Math.round(n).toString()};const log=(s,c='')=>{let d=document.createElement('div');d.className=c;d.textContent=new Date().toLocaleTimeString('fr-FR')+' — '+s;$('log').appendChild(d);$('log').scrollTop=1e6};const toast=s=>{$('toast').textContent=s;$('toast').classList.add('show');setTimeout(()=>$('toast').classList.remove('show'),3500)};
async function api(a,d={}){let r=await fetch('?api='+a,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(d)});let j;try{j=await r.json()}catch(e){throw Error('Réponse serveur invalide (HTTP '+r.status+')')}if(!j.ok)throw Error(j.error||'Erreur');return j}setInterval(()=>$('clock').textContent=new Date().toLocaleTimeString('fr-FR'),1000);
function setBusy(on,title='ANALYSE EN COURS',hint='L’IA construit le récit et dessine les scènes.'){ $('go').disabled=on;$('progress').classList.toggle('show',on);$('progressTitle').textContent=title;$('progressHint').textContent=hint;$('status').textContent=on?'WORKING':'READY';}
function safeSvgFragment(markup){const parser=new DOMParser(),doc=parser.parseFromString('<svg xmlns="'+NS+'">'+markup+'</svg>','image/svg+xml');if(doc.querySelector('parsererror'))return null;const allowed=new Set(['g','path','rect','circle','ellipse','line','polyline','polygon','text','tspan','defs','linearGradient','radialGradient','stop','clipPath']);const attrs=new Set(['x','y','x1','y1','x2','y2','cx','cy','r','rx','ry','width','height','d','points','fill','fill-opacity','stroke','stroke-width','stroke-opacity','stroke-linecap','stroke-linejoin','opacity','transform','text-anchor','font-family','font-size','font-weight','font-style','letter-spacing','dominant-baseline','offset','stop-color','stop-opacity','id','class','clip-path','gradientUnits','gradientTransform','viewBox','data-motion']);function clean(node){for(const child of [...node.children]){const tag=child.tagName;if(!allowed.has(tag)){child.remove();continue;}for(const at of [...child.attributes]){if(!attrs.has(at.name)||/^on/i.test(at.name)||/url\s*\(\s*(?!#)/i.test(at.value)||/javascript:/i.test(at.value)){child.removeAttribute(at.name);continue;}}clean(child);}}clean(doc.documentElement);return doc.documentElement;}
function sceneDuration(s){const txt=(s.narration||s.ecran||'').trim();const words=txt.split(/\s+/).filter(Boolean).length,chars=txt.length;const read=Math.max(words/2.5,chars/15);const visual= s.role==='hook'?2.2: s.role==='conclusion'?2.5:1.8;return Math.max(6.2,Math.min(35,read+visual));}
function renderScene(i){if(!scenes[i])return;const layer=$('sceneLayer');layer.replaceChildren();const g=document.createElementNS(NS,'g');g.setAttribute('class','sceneGroup active');const svg=safeSvgFragment(scenes[i].svg);if(svg){for(const child of [...svg.children])g.appendChild(document.importNode(child,true));}else{const bg=document.createElementNS(NS,'rect');bg.setAttribute('width','720');bg.setAttribute('height','1280');bg.setAttribute('fill','#172433');g.appendChild(bg);const t=document.createElementNS(NS,'text');t.setAttribute('x','360');t.setAttribute('y','630');t.setAttribute('fill','#fff');t.setAttribute('text-anchor','middle');t.setAttribute('font-size','28');t.textContent=scenes[i].ecran||scenes[i].titre;g.appendChild(t);}layer.appendChild(g);g.animate([{opacity:0,transform:'translateY(10px) scale(.992)'},{opacity:1,transform:'translateY(0) scale(1)'}],{duration:620,easing:'cubic-bezier(.2,.75,.2,1)',fill:'both'});g.querySelectorAll('[data-motion]').forEach((el,j)=>{const m=el.getAttribute('data-motion');let anim;if(m==='draw'&&el.hasAttribute('d')){try{const len=el.getTotalLength();el.style.strokeDasharray=len;el.style.strokeDashoffset=len;anim=el.animate([{strokeDashoffset:len},{strokeDashoffset:0}],{duration:1100,delay:100+j*35,easing:'ease-in-out',fill:'forwards'});}catch(e){}}else if(m==='rise'||m==='pop'||m==='fade'||m==='float'){const from=m==='rise'?{opacity:0,transform:'translateY(22px)'}:m==='pop'?{opacity:0,transform:'scale(.86)'}:m==='float'?{transform:'translateY(8px)'}:{opacity:0};const to=m==='float'?{transform:'translateY(-5px)'}:{opacity:1,transform:'translateY(0) scale(1)'};anim=el.animate([from,to],{duration:m==='float'?2600:850,delay:100+j*28,easing:'cubic-bezier(.2,.75,.2,1)',fill:'both',iterations:m==='float'?Infinity:1,direction:m==='float'?'alternate':'normal'});}if(anim){} });
 $('sceneCount').textContent=String(i+1).padStart(2,'0')+' / '+String(scenes.length).padStart(2,'0');$('narrationRole').textContent=(scenes[i].role||'SCÈNE').toUpperCase();$('narration').innerHTML='<small>'+esc((scenes[i].titre||'SCÈNE').toUpperCase())+'</small>'+esc(scenes[i].narration||scenes[i].ecran).replace(/\n/g,'<br>');$('factLine').textContent=scenes[i].fait_cle||scenes[i].transition||'—';$('readProgress').style.width=((i+1)/scenes.length*100)+'%';document.querySelectorAll('#storyNav button').forEach((b,j)=>b.classList.toggle('active',j===i));$('storyList').querySelectorAll('button').forEach((b,j)=>b.style.color=j===i?'#69e1e8':'');}
function sceneAt(t){let i=durations.findIndex((d,j)=>t>=starts[j]&&t<starts[j]+d);return i<0?scenes.length-1:i;}
function renderTime(t){t=Math.max(0,Math.min(total,t));const i=sceneAt(t);if(i!==current){current=i;renderScene(i);}const local=t-starts[i];$('timecode').textContent=clock(t)+' / '+clock(total);$('scrub').value=total?Math.round(t/total*1000):0;}
function clock(s){s=Math.max(0,Math.floor(s));return String(Math.floor(s/60)).padStart(2,'0')+':'+String(s%60).padStart(2,'0');}
function tick(now){if(!playing)return;const t=offset+(now-startedAt)/1000;renderTime(t);if(t>=total){playing=false;offset=total;$('play').textContent='▶';return;}raf=requestAnimationFrame(tick);}
function play(){if(!scenes.length)return;if(playing){playing=false;cancelAnimationFrame(raf);offset=Math.min(total,offset+(performance.now()-startedAt)/1000);$('play').textContent='▶';renderTime(offset);}else{if(offset>=total)offset=0;playing=true;startedAt=performance.now();$('play').textContent='Ⅱ';raf=requestAnimationFrame(tick);}}
function seek(t){if(playing){playing=false;cancelAnimationFrame(raf);$('play').textContent='▶';}offset=Math.max(0,Math.min(total,t));renderTime(offset);}
function makeStory(s){story=s;scenes=s.scenes;durations=scenes.map(sceneDuration);starts=[];total=0;durations.forEach(d=>{starts.push(total);total+=d;});current=-1;offset=0;renderTime(0);$('empty').style.display='none';$('stageStatus').textContent='AI GENERATED / SVG';$('storyNav').innerHTML='';$('storyList').innerHTML='';scenes.forEach((sc,i)=>{let b=document.createElement('button');b.textContent=String(i+1).padStart(2,'0');b.title=sc.titre;b.onclick=()=>seek(starts[i]);$('storyNav').appendChild(b);let row=document.createElement('button');row.innerHTML='<b>'+String(i+1).padStart(2,'0')+'</b> &nbsp;'+esc(sc.titre);row.onclick=()=>seek(starts[i]);$('storyList').appendChild(row);});$('timecode').textContent='00:00 / '+clock(total);$('model').textContent=$('model').dataset.value||'AI';let w=s['5w']||{};$('fivew').innerHTML=[['WHO / QUI','who'],['WHAT / QUOI','what'],['WHEN / QUAND','when'],['WHERE / OÙ','where'],['WHY / POURQUOI','why'],['HOW / COMMENT','how']].map(([label,key])=>'<div><b>'+label+'</b><span>'+esc(w[key]||'Non établi par les données.')+'</span></div>').join('');}
function showData(d){const a=d.author||{},v=d.video||{};$('source').textContent=(d.source||'—').toUpperCase();$('metrics').innerHTML=[['FOLLOWERS',fmt(a.followers)],['VIEWS',fmt(v.plays)],['LIKES',fmt(v.likes)],['COMMENTS',fmt(v.comments)]].map(([k,v])=>'<div class="metric"><span>'+k+'</span><b>'+v+'</b></div>').join('');$('accountInfo').textContent='@'+(a.id||'inconnu')+' · '+(a.nick||'')+(a.verified?' ✓':'')+'\n'+(a.bio||'Bio non disponible.')+'\nDurée : '+(v.duration||'—')+' s · Partages : '+fmt(v.shares);$('subs').textContent=d.subtitles||'Aucun sous-titre disponible. L’analyse s’appuiera sur la description et les données publiques.';$('subCount').textContent=(d.subtitles||'').length+' car.';}
$('go').onclick=async()=>{const url=$('url').value.trim();if(!url)return toast('Ajoute une URL TikTok.');setBusy(true,'COLLECTE DES DONNÉES','Récupération du compte, de la vidéo et des sous-titres.');log('Collecte des données TikTok…','info');try{const f=await api('fetch',{url});dataSet=f.data;showData(dataSet);log('Données collectées · source '+dataSet.source,'ok');setBusy(true,'ÉCRITURE & DIRECTION ARTISTIQUE','Agnès construit la progression 5W, rédige et dessine les scènes SVG. Cette étape peut prendre un peu de temps.');log('Agnès écrit le récit et génère les illustrations SVG scène par scène…','info');const r=await api('scenario',{data:dataSet});const s=r.scenario;$('model').dataset.value=r.model;$('model').textContent=r.model;makeStory(s);log('Récit reçu · '+scenes.length+' scènes · SVG individualisés.','ok');log('Durée calculée selon le volume de lecture : '+clock(total),'ok');$('play').textContent='Ⅱ';playing=true;startedAt=performance.now();raf=requestAnimationFrame(tick);$('status').textContent='PLAYING';$('fivew').scrollIntoView({block:'nearest',behavior:'smooth'}); }catch(e){log(e.message,'err');toast(e.message);$('status').textContent='ERROR';}finally{setBusy(false);}};
$('play').onclick=play;$('prev').onclick=()=>seek(starts[Math.max(0,current-1)]||0);$('next').onclick=()=>seek(starts[Math.min(scenes.length-1,current+1)]||0);$('scrub').oninput=e=>seek(total*(+e.target.value/1000));$('fs').onclick=()=>{const el=$('stageWrap');if(el.requestFullscreen)el.requestFullscreen();};
// Admin
const modal=$('modal');$('admBtn').onclick=async()=>{modal.style.display='block';try{const s=await fetch('?api=admin_state',{method:'POST',body:'{}'}).then(r=>r.json());$('mLabel').textContent=s.first?'CRÉER UN MOT DE PASSE ADMIN (10+ CARACTÈRES)':'MOT DE PASSE ADMIN';if(s.logged)loadAdmin();else{$('mLogin').style.display='';$('mForm').style.display='none';}}catch(e){toast('Impossible de vérifier la session.');}};$('mclose').onclick=()=>modal.style.display='none';$('mgo').onclick=async()=>{try{await api('admin_login',{pw:$('mpw').value});$('mpw').value='';await loadAdmin();}catch(e){toast(e.message);}};
async function loadAdmin(){try{const r=await api('admin_get');const c=r.config;csrf=c.csrf;defaults=c.defaults;$('c_ps').value=c.prompt_system;$('c_pu').value=c.prompt_user;$('c_mod').value=(c.models||[]).join(', ');$('c_t').value=c.temperature;$('c_mt').value=c.max_tokens;$('c_ns').value=c.nscenes;$('c_rl').value=c.rate_per_hour;$('c_k').value=(c.keys||[]).join('\n');$('mLogin').style.display='none';$('mForm').style.display='';}catch(e){toast(e.message);}}
$('rst').onclick=()=>{$('c_ps').value=defaults.prompt_system;$('c_pu').value=defaults.prompt_user;};$('msave').onclick=async()=>{try{await api('admin_save',{csrf,config:{prompt_system:$('c_ps').value,prompt_user:$('c_pu').value,models:$('c_mod').value,temperature:$('c_t').value,max_tokens:$('c_mt').value,nscenes:$('c_ns').value,rate_per_hour:$('c_rl').value,keys:$('c_k').value,new_pw:$('c_pw').value}});$('c_pw').value='';toast('Configuration enregistrée.');}catch(e){toast(e.message);}};$('mout').onclick=async()=>{await api('admin_logout',{csrf}).catch(()=>{});modal.style.display='none';};
</script></body></html>
  
